// ---- Simple enum ----
enum Direction {
    Up,
    Down,
    Left,
    Right,
}

// ---- Enum with data ----
enum PlayerAction {
    Move(Direction),
    Attack { target: String, damage: i32 },
    Jump(i32),
    UseItem(String),
    Wait,
}

// ---- Enum with different types ----
enum GameResult {
    Win { score: i32 },
    Lose { reason: String },
    Draw,
}

// ---- Enum with methods ----
impl Direction {
    fn opposite(&self) -> Direction {
        match self {
            Direction::Up => Direction::Down,
            Direction::Down => Direction::Up,
            Direction::Left => Direction::Right,
            Direction::Right => Direction::Left,
        }
    }
}

impl PlayerAction {
    fn description(&self) -> String {
        match self {
            PlayerAction::Move(dir) => format!("Moving {:?}", dir),
            PlayerAction::Attack { target, damage } => format!("Attacking {} for {}", target, damage),
            PlayerAction::Jump(height) => format!("Jumping {} meters", height),
            PlayerAction::UseItem(item) => format!("Using {}", item),
            PlayerAction::Wait => String::from("Waiting"),
        }
    }
}

fn main() {
    // ---- Using enums ----
    let dir = Direction::Up;
    let opposite = dir.opposite();
    println!("Direction: {:?}, Opposite: {:?}", dir, opposite);

    // ---- Enum with data ----
    let actions = vec![
        PlayerAction::Move(Direction::Right),
        PlayerAction::Attack { target: String::from("Goblin"), damage: 20 },
        PlayerAction::Jump(5),
        PlayerAction::UseItem(String::from("Health Potion")),
        PlayerAction::Wait,
    ];

    for action in actions {
        println!("Action: {}", action.description());
    }

    // ---- GameResult ----
    let result = GameResult::Win { score: 1000 };
    let result2 = GameResult::Lose { reason: String::from("Out of lives") };
    let result3 = GameResult::Draw;

    match result {
        GameResult::Win { score } => println!("🎉 You won with score: {}", score),
        GameResult::Lose { reason } => println!("💀 You lost: {}", reason),
        GameResult::Draw => println!("🤝 It's a draw!"),
    }

    // ---- Option enum (Rust's null) ----
    let some_number = Some(42);
    let no_number: Option<i32> = None;

    if let Some(n) = some_number {
        println!("Number: {}", n);
    }

    // ---- Result enum (Rust's error handling) ----
    let result: Result<i32, &str> = Ok(42);
    let error: Result<i32, &str> = Err("Something went wrong");

    match result {
        Ok(value) => println!("Success: {}", value),
        Err(e) => println!("Error: {}", e),
    }
}

